CREATE OR REPLACE FUNCTION register_user_and_tenant(user_id UUID, tenant_name TEXT) RETURNS UUID AS $$ DECLARE new_tenant_id UUID; BEGIN INSERT INTO public.tenants (name) VALUES (tenant_name) RETURNING id INTO new_tenant_id; INSERT INTO public.users_tenants (user_id, tenant_id, role) VALUES (user_id, new_tenant_id, 'admin'); EXECUTE 'CREATE SCHEMA IF NOT EXISTS tenant_' || new_tenant_id; RETURN new_tenant_id; END; $$ LANGUAGE plpgsql SECURITY DEFINER; GRANT EXECUTE ON FUNCTION register_user_and_tenant TO authenticated; GRANT EXECUTE ON FUNCTION register_user_and_tenant TO anon;
